WITH deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY country ORDER BY started_at NULLS LAST, id) AS latest_rank FROM sessions QUALIFY latest_rank = 1) SELECT DATE_TRUNC('WEEK', started_at) AS week_start, device, COUNT(*) AS event_count, COUNT(CASE WHEN browser = 'Edge' THEN 1 END) AS edge_count, MIN(started_at) AS first_started_at, COUNT(DISTINCT browser) AS distinct_browsers FROM deduped GROUP BY GROUPING SETS ((DATE_TRUNC('WEEK', started_at), device), (DATE_TRUNC('WEEK', started_at)), ());
